```c
static uint64_t
compute_chunk_unpack_size (
    int y, int width, int height, int lpc, const struct _internal_exr_part* part)
{
    uint64_t unpacksize = 0;
    if (part->chan_has_line_sampling || height != lpc)
    {
        const exr_attr_chlist_t* chanlist = part->channels->chlist;
        for (int c = 0; c < chanlist->num_channels; ++c)
        {
            const exr_attr_chlist_entry_t* curc = (chanlist->entries + c);
            uint64_t chansz = ((curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4);
            chansz *= ((uint64_t) width);
            if (curc->x_sampling > 1) chansz /= ((uint64_t) curc->x_sampling);
            chansz *= ((uint64_t) height);
            if (curc->y_sampling > 1)
            {
                if (height > 1)
                {
                    if (curc->y_sampling > height)
                        chansz /= ((uint64_t) height);
                    else
                        chansz /= ((uint64_t) curc->y_sampling);
                }
                else if ((y % ((int) curc->y_sampling)) != 0)
                    chansz = 0;
            }
            unpacksize += chansz;
        }
    }
    else
        unpacksize = part->unpacked_size_per_chunk;
    return unpacksize;
}
```

So for a chunk with `chan_has_line_sampling` (i.e., at least one channel has y_sampling > 1), the unpacked size is computed as:

For each channel:
- `chansz = bpc * width`
- If `x_sampling > 1`: `chansz /= x_sampling` → `bpc * width / x_sampling`
- `chansz *= height` → `bpc * width * height / x_sampling`
- If `y_sampling > 1`:
  - If `height > 1`:
    - If `y_sampling > height`: `chansz /= height` → `bpc * width / x_sampling`
    - Else: `chansz /= y_sampling` → `bpc * width * height / (x_sampling * y_sampling)`
  - Else if `(y % y_sampling) != 0`: `chansz = 0`

So the unpacked size for a channel with y_sampling > 1 and height > 1 is `bpc * width * height / (x_sampling * y_sampling)`.

But in `generic_unpack`, the actual bytes read for that channel is:
- For each y in `[0, chunk.height)`:
